for n in [1,2,3]:
    d=G[f'Demo pair {n} input']; o=G[f'Demo pair {n} output']
    Ms=[]
    for a,b in cols:
        ms=np.array([[1 if d[r][c]!=0 else 0 for c in range(a,b)] for r in range(4)])
