    # dihedral-normalized equivalence among bands
    def norm(m):
        for flip in [m, m[::-1], m[:,::-1], m[::-1,:: -1]]:
            for rot in range(4):
                s=flip.T.rotated(rot)%4
                res=tuple(tuple(int(x) for x in r) for r in s)
                yield res
    uniq={min(norm(Ms[i])) for i in range(4)}
    print('pair',n,'colors',[d[0][cols[j][0]] for j in range(4)],'dihedral classes equal?', len(uniq)==1)
