G=load()
def solve(D):
    D=np.array(D); H,W=D.shape
    seen=np.zeros_like(D,bool); comps=[]
    for r in range(H):
        for c in range(W):
            if D[r,c]!=0 and not seen[r,c]:
                col=D[r,c]; st=[(r,c)]; seen[r,c]=True; cells=[]
                while st:
                    a,b=st.pop(); cells.append((a,b))
                    for da in (-1,0,1):
                        for db in (-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<H and 0<=y<W and D[x,y]==col and not seen[x,y]:
                                seen[x,y]=True; st.append((x,y))
                comps.append((col,cells))
    bcolors=[c for c,_ in sorted(comps,key=lambda x:min(x[1]))]
    Ms=[]
    for col,cells in sorted(comps,key=lambda x:min(x[1])):
        rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
        h=w=max(rs)-min(rs)+1=max(cs)-min(cs)+1
        m=[[0]*w for _ in range(h)]
        for (rr,cc) in cells: m[rr-min(rs)][cc-min(cs)]=1
        Ms.append(m)
    res=[]
    for r in range(4):
        row=[]
        for c in range(4):
            cov=[i for i,m_ in enumerate(Ms) if m_[r][c]]
            if not cov: row.append(0); continue
            row.append(bcolors[min(cov,key=lambda i:(Ms[i]).sum())])
        res.append(row)
    return res
